from AlgorithmImports import *
from math import floor


class StrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(20)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.SetWarmUp(30, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = data.Bars

        spy_bar = bars[self.spy] if bars.ContainsKey(self.spy) else None
        aapl_bar = bars[self.aapl] if bars.ContainsKey(self.aapl) else None

        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.previous_aapl_close = aapl_bar.Close

        all_bars_present = all(
            bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        spy_crosses_above = False
        spy_crosses_below = False

        if (
            spy_bar is not None
            and self.spy_sma.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        ):
            current_spy_sma = self.spy_sma.Current.Value
            spy_crosses_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_bar.Close > current_spy_sma
            )
            spy_crosses_below = (
                self.previous_spy_close >= self.previous_spy_sma
                and spy_bar.Close < current_spy_sma
            )

        indicators_ready = self.spy_sma.IsReady and self.aapl_rsi.IsReady

        if all_bars_present and indicators_ready and not self.IsWarmingUp:
            if self.strategy_a_lot > 0 and spy_crosses_below:
                self.MarketOrder(
                    self.spy,
                    -self.strategy_a_lot,
                    tag="Strategy A sell"
                )
                self.strategy_a_lot = 0

            if (
                self.strategy_b_lot > 0
                and self.aapl_rsi.Current.Value > 60
            ):
                self.MarketOrder(
                    self.aapl,
                    -self.strategy_b_lot,
                    tag="Strategy B sell"
                )
                self.strategy_b_lot = 0

            if self.strategy_a_lot == 0 and spy_crosses_above:
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(
                        self.spy,
                        quantity,
                        tag="Strategy A buy"
                    )
                    self.strategy_a_lot = quantity

            if (
                self.strategy_b_lot == 0
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = floor(20_000 / aapl_bar.Close)
                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B buy"
                    )
                    self.strategy_b_lot = quantity

        if spy_bar is not None and self.spy_sma.IsReady:
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = self.spy_sma.Current.Value

from AlgorithmImports import *


class StrategySystemAlgorithm(QCAlgorithm):
    SMA_PERIOD = 20
    AAPL_RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.sma(
            self.spy,
            self.SMA_PERIOD,
            Resolution.DAILY
        )
        self.aapl_rsi = self.rsi(
            self.aapl,
            self.AAPL_RSI_PERIOD,
            MovingAverageType.WILDERS,
            Resolution.DAILY
        )

        self.spy_sma_points = []
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False
        self.order_owners = {}

    def on_data(self, data: Slice):
        self._synchronize_lots()

        if self.spy in data.bars and self.spy_sma.is_ready:
            self.spy_sma_points.append(
                (float(data.bars[self.spy].close),
                 float(self.spy_sma.current.value))
            )
            if len(self.spy_sma_points) > 2:
                self.spy_sma_points.pop(0)

        if self.aapl in data.bars:
            aapl_close = float(data.bars[self.aapl].close)

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close

        if any(symbol not in data.bars for symbol in self.symbols):
            return

        if (
            not self.spy_sma.is_ready
            or len(self.spy_sma_points) < 2
            or not self.aapl_rsi.is_ready
            or self.aapl_previous_close is None
        ):
            return

        previous_spy_close, previous_spy_sma = self.spy_sma_points[0]
        current_spy_close, current_spy_sma = self.spy_sma_points[1]
        current_aapl_close = float(data.bars[self.aapl].close)

        spy_crosses_below = (
            previous_spy_close >= previous_spy_sma
            and current_spy_close < current_spy_sma
        )
        spy_crosses_above = (
            previous_spy_close <= previous_spy_sma
            and current_spy_close > current_spy_sma
        )

        if (
            self.strategy_a_quantity > 0
            and not self.strategy_a_pending
            and spy_crosses_below
        ):
            self._submit_order(
                self.spy,
                -self.strategy_a_quantity,
                "A",
                "Strategy A sell"
            )

        if (
            self.strategy_b_quantity > 0
            and not self.strategy_b_pending
            and float(self.aapl_rsi.current.value) > 60
        ):
            self._submit_order(
                self.aapl,
                -self.strategy_b_quantity,
                "B",
                "Strategy B sell"
            )

        if (
            self.strategy_a_quantity == 0
            and not self.strategy_a_pending
            and spy_crosses_above
        ):
            quantity = int(self.calculate_order_quantity(self.spy, 0.40))
            if quantity > 0:
                self._submit_order(
                    self.spy,
                    quantity,
                    "A",
                    "Strategy A buy"
                )

        if (
            self.strategy_b_quantity == 0
            and not self.strategy_b_pending
            and self.aapl_red_streak >= 3
            and float(self.portfolio.cash) >= 20_000
        ):
            quantity = int(20_000 // current_aapl_close)
            if quantity > 0:
                self._submit_order(
                    self.aapl,
                    quantity,
                    "B",
                    "Strategy B buy"
                )

    def _submit_order(self, symbol, quantity, owner, tag):
        if owner == "A":
            self.strategy_a_pending = True
        else:
            self.strategy_b_pending = True

        ticket = self.market_order(symbol, quantity, tag=tag)
        self.order_owners[ticket.order_id] = owner

    def on_order_event(self, order_event: OrderEvent):
        owner = self.order_owners.get(order_event.order_id)
        if owner is None:
            return

        fill_quantity = int(order_event.fill_quantity)

        if fill_quantity != 0:
            if owner == "A":
                self.strategy_a_quantity = max(
                    0,
                    self.strategy_a_quantity + fill_quantity
                )
            else:
                self.strategy_b_quantity = max(
                    0,
                    self.strategy_b_quantity + fill_quantity
                )

        if order_event.status in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        ):
            if owner == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False

            del self.order_owners[order_event.order_id]

    def _synchronize_lots(self):
        if not self.strategy_a_pending:
            self.strategy_a_quantity = max(
                0,
                int(self.portfolio[self.spy].quantity)
            )

        if not self.strategy_b_pending:
            self.strategy_b_quantity = max(
                0,
                int(self.portfolio[self.aapl].quantity)
            )

